const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);document.querySelector('nav').classList.toggle('open',open)});
document.querySelector('.legal-toggle').addEventListener('click',e=>{const box=document.querySelector('#legal');box.hidden=!box.hidden;e.currentTarget.setAttribute('aria-expanded',!box.hidden)});
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('animated');obs.observe(el)})}
document.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const body=`Nom : ${d.get('nom')}\nE-mail : ${d.get('email')}\nTéléphone : ${d.get('telephone')}\nCommune : ${d.get('commune')}\nActivité : ${d.get('activite')}\n\n${d.get('message')}`;location.href=`mailto:rv.services@free.fr?subject=${encodeURIComponent('Demande de devis — '+d.get('activite'))}&body=${encodeURIComponent(body)}`;document.querySelector('#form-status').textContent='Votre messagerie est sollicitée. Vérifiez le message puis envoyez-le. Si elle ne s’ouvre pas, écrivez à rv.services@free.fr.'});
